function LoanComingSoon({ defaultType }) {
  const { loanType } = useParams();
  const location = useLocation();
  const canvasRef = useRef(null);
  const [showContent, setShowContent] = useState(false);

  // Determine current loan type from url or prop
  let currentKey = defaultType || loanType;
  if (!currentKey) {
    const pathname = location.pathname.toLowerCase();
    if (pathname.includes('home-loan')) currentKey = 'home-loan';
    else if (pathname.includes('personal-loan')) currentKey = 'personal-loan';
    else if (pathname.includes('instasalary')) currentKey = 'instasalary';
    else if (pathname.includes('property')) currentKey = 'loan-against-property';
    else if (pathname.includes('auto-loan')) currentKey = 'auto-loan';
    else if (pathname.includes('education-loan')) currentKey = 'education-loan';
    else currentKey = 'personal-loan';
  }

  const details = LOAN_DETAILS[currentKey] || {
    title: 'Loan Services',
    subtitle: 'Fast, secure, and affordable loan solutions tailored for you.',
    benefits: [
      'Best Interest Rates',
      'Quick Online Approval',
      'Minimal Documentation',
      'Trusted Lending Partners',
      '24/7 Dedicated Support',
    ],
    description:
      'Our upcoming Loan services will provide seamless financing options to support all your financial needs.',
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let animationFrameId;

    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    const particles = [];
    const particleCount = 200;

    class Particle {
      constructor(isBlast) {
        this.x = isBlast ? canvas.width / 2 : Math.random() * canvas.width;
        this.y = isBlast ? canvas.height / 2 : -10;
        this.size = Math.random() * 5 + 2;
        this.speedX = (Math.random() - 0.5) * (isBlast ? 30 : 2);
        this.speedY = isBlast ? (Math.random() - 0.5) * 30 : Math.random() * 3 + 1;
        this.color = `hsl(${Math.random() * 360}, 100%, 50%)`;
      }

      update() {
        this.x += this.speedX;
        this.y += this.speedY;
        if (this.size > 0.2) this.size -= 0.1;

        if (this.y > canvas.height) {
          this.y = -10;
          this.x = Math.random() * canvas.width;
        }
      }

      draw() {
        ctx.fillStyle = this.color;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // Initial blast
    for (let i = 0; i < particleCount; i++) {
      particles.push(new Particle(true));
    }

    let blastDuration = 0;
    const maxBlastDuration = 30;

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      particles.forEach((p, i) => {
        p.update();
        p.draw();
        if (p.size <= 0.2) particles.splice(i, 1);
      });

      blastDuration++;

      if (blastDuration >= maxBlastDuration) {
        while (particles.length < particleCount) {
          particles.push(new Particle(false));
        }
        setShowContent(true);
      }

      animationFrameId = requestAnimationFrame(animate);
    };

    animate();

    const handleResize = () => {
      if (canvas) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }
    };

    window.addEventListener('resize', handleResize);

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  return (
    <div className="coming-soon-container">
      <canvas ref={canvasRef} id="celebration-canvas"></canvas>

      <div className={`content contentcomming container ${showContent ? 'show' : ''}`}>
        <div className="row justify-content-center">
          <div className="col-md-8 text-center">
            <h1 className="display-2 fw-bold mb-4" style={{ color: 'var(--bs-primary2)' }}>
              Exciting News!
            </h1>

            <h2 className="display-4 text-secondary mb-4 customeh1textcoming">
              {details.title} Service is Coming Soon!
            </h2>

            <p className="lead mb-5 celebrationh2">{details.subtitle}</p>

            <p className="mb-4 fw-semibold">Discover what’s coming:</p>

            <ul className="list-unstyled mb-5">
              {details.benefits.map((benefit, idx) => (
                <li key={idx} className="mb-2">
                  ✓ {benefit}
                </li>
              ))}
            </ul>

            <p className="mb-4 text-muted">{details.description}</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default LoanComingSoon;
